sqlEquivalent:
CREATE TABLE lab_accounts (id SERIAL PRIMARY KEY, username VARCHAR(80) UNIQUE NOT NULL);
CREATE TABLE lab_settings (
  id SERIAL PRIMARY KEY,
  theme VARCHAR(40) DEFAULT 'system',
  account_id INTEGER UNIQUE NOT NULL REFERENCES lab_accounts(id)
);

starterCode:
// JavaScript track — same Prisma DSL
model LabAccount {
  id Int @id @default(autoincrement())
  username String @unique
  settings LabSettings?
  @@map("lab_accounts")
}
model LabSettings {
  id Int @id @default(autoincrement())
  theme String @default("system")
  accountId Int @unique @map("account_id")
  account LabAccount @relation(fields: [accountId], references: [id])
  @@map("lab_settings")
}

